//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn attribute_clone_real_leaf_identity_exact_fields_values_owners_and_author_state(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,'Root'),other=document.implementation.createHTMLDocument('other'),templateOwner=document.createElement('template').content.ownerDocument,raw='\ud800',name='\ud800:Case\udfff',source=xml.createAttributeNS(raw,name);source.value='\ud800A\udfff';source.bindingState={held:source};var copies=[source.cloneNode(),source.cloneNode(true),document.importNode(source),other.importNode(source,true),xml.importNode(source,{selfOnly:true}),templateOwner.importNode(source)];for(var i=0;i<copies.length;i++){var copy=copies[i],expected=i<2?xml:i===2?document:i===3?other:i===4?xml:templateOwner;if(copy===source||!(copy instanceof Attr)||!(copy instanceof Node)||copy.ownerElement!==null||copy.parentNode!==null||copy.ownerDocument!==expected||copy.name!==name||copy.prefix!==raw||copy.localName!=='Case\udfff'||copy.namespaceURI!==raw||copy.value!==source.value||copy.value.charCodeAt(0)!==0xd800||copy.bindingState!==undefined||copy.childNodes.length||copy.childNodes!==copy.childNodes)throw 'genuine independent Attr clone';for(var j=0;j<i;j++)if(copy===copies[j])throw 'distinct native identities';copy.value='independent';}if(source.value!=='\ud800A\udfff'||source.bindingState.held!==source)throw 'copy never aliases source payload or author state';
var node=other.createElement('span'),attached=xml.createAttribute('data-note');attached.value='\ud800';node.setAttributeNode(attached);var watcher=new MutationObserver(function(){});watcher.observe(node,{attributes:true,attributeOldValue:true});xml.adoptNode(attached);var copy=attached.cloneNode(true);if(copy.ownerDocument!==xml||copy.ownerElement!==null||copy.value.charCodeAt(0)!==0xd800||attached.ownerElement!==node||attached.ownerDocument!==xml||watcher.takeRecords().length||node.getAttributeNode('data-note')!==attached)throw 'attached clone reads actual value and associated document without source mutation';copy.value='changed';if(node.getAttribute('data-note').charCodeAt(0)!==0xd800)throw 'attached source value retained';
"#);
}
#[test]
fn attribute_clone_import_dictionary_reentry_and_protected_other_sources_keep_actual_documents(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,'Root'),other=document.implementation.createHTMLDocument('other'),node=other.createElement('span'),source=xml.createAttribute('data-note');source.value='first';node.setAttributeNode(source);var calls=0,copy=xml.importNode(source,{get selfOnly(){calls++;node.removeAttributeNode(source);source.value='updated';return true;}});if(calls!==1||copy===source||copy.value!=='updated'||copy.ownerDocument!==xml||copy.ownerElement!==null||source.ownerElement!==null||source.ownerDocument!==other)throw 'dictionary callback completes before actual clone snapshot';var coerced=0,deep={valueOf:function(){coerced++;return 1;},toString:function(){coerced++;return 'deep';}};source.cloneNode(deep);if(coerced)throw 'boolean deep does not run author conversion';var caught=false;try{xml.importNode(other.createElement('span'));}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||xml.documentElement.attributes.length||other.body.childNodes.length)throw 'unsupported general inert tree import stays typed without false publication';caught=false;try{Node.prototype.cloneNode.call({});}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine clone Node brand';
"#);
}
#[test]
fn attribute_clone_saved_child_realm_origin_precedes_import_dictionary_or_identity(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,''),source=xml.createAttribute('data-note');source.value='held';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,savedClone=w.Node.prototype.cloneNode,savedImport=w.Document.prototype.importNode,calls=0,options={get selfOnly(){calls++;return true;}},copy=savedClone.call(source,true),imported=savedImport.call(xml,source,options);if(copy===source||copy.ownerDocument!==xml||imported.ownerDocument!==xml||copy.value!=='held'||calls!==1||Object.getPrototypeOf(savedClone)!==w.Function.prototype)throw 'actual child realm leaf operations';
"#);page.set_location(&crate::navigation::address("https://other-attr-clone.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits);for expression in ["savedClone.call(source,true);","savedImport.call(xml,source,options);"]{assert_eq!(page.console_eval(&mut doc,&mut forms,expression).errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits),before);}run(&mut doc,&mut forms,&mut page,"if(calls!==1||source.value!=='held')throw 'origin before dictionary and identity';");
}

#[test]
fn attribute_clone_author_fields_use_real_bounded_store_without_native_value_getters_or_origin_bypass(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var source=document.createAttribute('data-note');source.value='native';var hits=0,state={held:source},symbol=Symbol('binding');Object.defineProperty(source,'bindingState',{enumerable:true,configurable:true,get:function(){hits++;return state;}});source[symbol]=17;Object.defineProperty(source,'value',{configurable:true,get:function(){hits++;return 'author';}});var copy=source.cloneNode(true);if(hits!==0||copy.value!=='native'||copy.bindingState!==undefined||copy[symbol]!==undefined||Object.keys(source).indexOf('bindingState')<0||Object.getOwnPropertySymbols(source)[0]!==symbol||Object.getOwnPropertySymbols(copy).length)throw 'native leaf copy ignores author fields and value getter';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var read=frame.contentWindow.Function('node','return node.bindingState;');if(read(source)!==state||hits!==1)throw 'actual same-origin Attr author store';
"#);let before=(doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits);let allowance=page.runtime.event_property_allowance_for_test(0);assert_eq!(page.console_eval(&mut doc,&mut forms,"source.unpublishedBinding=17;").errors,1);page.runtime.event_property_allowance_for_test(allowance);assert_eq!((doc.nodes.len(),page.state.attributes.len(),page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(Object.hasOwn(source,'unpublishedBinding')||source[symbol]!==17||hits!==1||Object.getOwnPropertyDescriptor(Attr.prototype,'value').get.call(source)!=='native')throw 'author store refusal leaves native and ordinary records';");page.set_location(&crate::navigation::address("https://other-attr-author.test/",&crate::navigation::Location::home()).unwrap());assert_eq!(page.console_eval(&mut doc,&mut forms,"read(source);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());run(&mut doc,&mut forms,&mut page,"if(hits!==1||copy.value!=='native')throw 'origin guard before Attr author getter';");
}
